inline int64_t Rescoped(int64_t x) {
    if (x > 0) {
        const int64_t z = canon::AddInt(x, 1);
        if (z > 5) {
            return z;
        }
    } else {
        return canon::SubInt(0, x);
    }
    const int64_t z = canon::MulInt(x, 2);
    return z;
}

inline std::string Echo(std::string_view s) {
    const std::string copy(s);
    return copy;
}

inline std::string PickShelf(bool front) {
    if (front) {
        return "front";
    }
    return "back";
}

inline double Unit(double x) {
    x = canon::CheckFloatArg(x);
    x = canon::CheckFloatRange(x, 0.0, 0.9999999999999999);
    return x;
}

inline int64_t Inc(int64_t new_) {
    const int64_t long_ = canon::AddInt(new_, 1);
    return long_;
}

inline int64_t IncTwice(int64_t x) {
    return Inc(Inc(x));
}

/// Every @reload value of package demo.shop, loaded together and never modified.
/// A reload builds a new snapshot; readers keep the one they hold.
class ShopSnapshot {
public:
    ShopSnapshot() = default;
    ShopSnapshot(const ShopSnapshot&) = delete;
    ShopSnapshot& operator=(const ShopSnapshot&) = delete;
    ShopSnapshot(ShopSnapshot&&) = default;
    ShopSnapshot& operator=(ShopSnapshot&&) = default;

    /// Reads items.json, config.json from `dir`. Returns nullptr and sets `error` if a file is
    /// missing, is not JSON, or was built from another schema. Values are not
    /// validated here: `canon build` already did, and filled every default.
    static std::shared_ptr<const ShopSnapshot> Load(const std::string& dir, std::string& error);

    /// Everything on sale.
    const Items& GetItems() const { return items_; }

    const Config& GetConfig() const { return config_; }

private:
    friend struct detail::ShopAccess;

    Items items_;
    Config config_;
};

/// The current snapshot of package demo.shop.
///   auto snap = ShopStore::Current();   // hold it for one tick or request
///   ShopStore::Reload(dir, error);      // the old snapshot lives while someone holds it
/// Current() is nullptr until the first successful Reload.
class ShopStore {
public:
    static std::shared_ptr<const ShopSnapshot> Current() { return current_.Load(); }

    /// Loads a new snapshot from `dir` and swaps it in. On failure the current
    /// snapshot stays, `error` is set and the result is false.
    static bool Reload(const std::string& dir, std::string& error);

private:
    friend struct detail::ShopAccess;

    static inline canon::AtomicSharedPtr<const ShopSnapshot> current_;
};

